// Viewer's typed attributes, generated by tools/node_attributes.py from node_definitions.usda: its
// inputs and properties, read by name, and its outputs, committed by name. Don't edit it: change the
// definition and run `uv run python tools/node_attributes.py render`.
#pragma once

#include <pxr/pxr.h>

#include "node_input_reader.h"
#include "node_roles.h"

namespace proscenium {

struct ViewerInputs {
  static constexpr const char* kLayer = "inputs:layer";
  static constexpr const char* kContext = "props:context";

  LayerInput layer{};
  bool context{};
};

inline ViewerInputs ReadViewerInputs(const NodeInputReader& reader) {
  ViewerInputs inputs;
  inputs.layer = reader.Layer("inputs:layer");
  inputs.context = reader.Value<bool>("props:context");
  return inputs;
}

// What the node outputs; an output left empty, such as a null layer, commits nothing.
struct ViewerOutputs {};

inline ValueOutputs WriteViewerOutputs(const ViewerOutputs& outputs) {
  ValueOutputs values;
  static_cast<void>(outputs);
  return values;
}

}  // namespace proscenium
